use pfx_vector_core::{Angle,CoreError,CoreResult,EllipticalArc,Path,PathBuilder,Point2,Vector2};
use super::SvgPathCommand;
fn resolve(base:Point2,x:f64,y:f64,relative:bool)->Point2{if relative{Point2::new(base.x+x,base.y+y)}else{Point2::new(x,y)}}
pub fn svg_arc_to_center(start:Point2,end:Point2,rx:f64,ry:f64,rotation_deg:f64,large_arc:bool,sweep:bool)->CoreResult<Option<EllipticalArc>>{let mut rx=rx.abs();let mut ry=ry.abs();if rx==0.0||ry==0.0{return Ok(None)}if start==end{return Ok(None)}let phi=rotation_deg.to_radians();let(cphi,sphi)=phi.cos_sin();let dx=(start.x-end.x)*0.5;let dy=(start.y-end.y)*0.5;let xp=cphi*dx+sphi*dy;let yp=-sphi*dx+cphi*dy;let lambda=xp*xp/(rx*rx)+yp*yp/(ry*ry);if lambda>1.0{let k=lambda.sqrt();rx*=k;ry*=k;}let num=(rx*rx*ry*ry-rx*rx*yp*yp-ry*ry*xp*xp).max(0.0);let den=rx*rx*yp*yp+ry*ry*xp*xp;let sign=if large_arc==sweep{-1.0}else{1.0};let coef=if den==0.0{0.0}else{sign*(num/den).sqrt()};let cxp=coef*(rx*yp/ry);let cyp=coef*(-ry*xp/rx);let cx=cphi*cxp-sphi*cyp+(start.x+end.x)*0.5;let cy=sphi*cxp+cphi*cyp+(start.y+end.y)*0.5;let angle_between=|u:Vector2,v:Vector2|{let dot=u.dot(v);let cross=u.cross(v);cross.atan2(dot)};let u=Vector2::new((xp-cxp)/rx,(yp-cyp)/ry);let v=Vector2::new((-xp-cxp)/rx,(-yp-cyp)/ry);let theta1=angle_between(Vector2::new(1.0,0.0),u);let mut delta=angle_between(u,v);if !sweep&&delta>0.0{delta-=core::f64::consts::TAU}else if sweep&&delta<0.0{delta+=core::f64::consts::TAU}Ok(Some(EllipticalArc::new(Point2::new(cx,cy),rx,ry,Angle::radians(phi),Angle::radians(theta1),Angle::radians(delta))))}
pub fn normalize_path_commands(commands:&[SvgPathCommand])->CoreResult<Path>{let mut b=PathBuilder::new();let mut current=Point2::new(0.0,0.0);let mut sub_start=None;let mut last_cubic:Option<Point2>=None;let mut last_quad:Option<Point2>=None;for cmd in commands{match *cmd{SvgPathCommand::Move{relative,x,y}=>{current=resolve(current,x,y,relative);b.move_to(current)?;sub_start=Some(current);last_cubic=None;last_quad=None},SvgPathCommand::Line{relative,x,y}=>{current=resolve(current,x,y,relative);b.line_to(current)?;last_cubic=None;last_quad=None},SvgPathCommand::Horizontal{relative,x}=>{current=Point2::new(if relative{current.x+x}else{x},current.y);b.line_to(current)?;last_cubic=None;last_quad=None},SvgPathCommand::Vertical{relative,y}=>{current=Point2::new(current.x,if relative{current.y+y}else{y});b.line_to(current)?;last_cubic=None;last_quad=None},SvgPathCommand::Cubic{relative,x1,y1,x2,y2,x,y}=>{let c1=resolve(current,x1,y1,relative);let c2=resolve(current,x2,y2,relative);let p=resolve(current,x,y,relative);b.cubic_to(c1,c2,p)?;current=p;last_cubic=Some(c2);last_quad=None},SvgPathCommand::SmoothCubic{relative,x2,y2,x,y}=>{let c1=last_cubic.map_or(current,|q|current+(current-q));let c2=resolve(current,x2,y2,relative);let p=resolve(current,x,y,relative);b.cubic_to(c1,c2,p)?;current=p;last_cubic=Some(c2);last_quad=None},SvgPathCommand::Quadratic{relative,x1,y1,x,y}=>{let c1=resolve(current,x1,y1,relative);let p=resolve(current,x,y,relative);b.quad_to(c1,p)?;current=p;last_quad=Some(c1);last_cubic=None},SvgPathCommand::SmoothQuadratic{relative,x,y}=>{let c1=last_quad.map_or(current,|q|current+(current-q));let p=resolve(current,x,y,relative);b.quad_to(c1,p)?;current=p;last_quad=Some(c1);last_cubic=None},SvgPathCommand::Arc{relative,rx,ry,rotation,large_arc,sweep,x,y}=>{let p=resolve(current,x,y,relative);if let Some(a)=svg_arc_to_center(current,p,rx,ry,rotation,large_arc,sweep)?{b.arc_to(a)?;}else if current!=p{b.line_to(p)?;}current=p;last_cubic=None;last_quad=None},SvgPathCommand::Close=>{b.close()?;current=sub_start.ok_or(CoreError::InvalidGeometry)?;sub_start=None;last_cubic=None;last_quad=None}}}b.finish()}
